//! Independent ABI and deposit-ID fixtures generated by @arbitrum/sdk 4.1.0.
//! All addresses and amounts in the fixtures are synthetic; no RPC is used.
use gofin_bridge::canonical::{
    CanonicalChildReceipt, CanonicalChildTransaction, CanonicalDepositReceipt, ExpectedEthDeposit,
    verify_eth_deposit_child, verify_eth_deposit_source,
};

#[test]
fn published_sdk_events_and_child_hashes_match_both_reviewed_deployments() {
    let fixtures: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/canonical_sdk_events.json")).unwrap();
    assert_eq!(fixtures["provenance"]["version"], "4.1.0");
    assert_eq!(
        fixtures["provenance"]["dist.integrity"],
        "sha512-OIGxZj4DHROejCjSkaZEOcHhRktZGMhLAPA+Cyymlp1z7KdWaeN2DW85i6yd2Ks7QeZkv2EvwcBKOJnxoSI5tQ=="
    );
    let cases = fixtures["fixtures"].as_array().unwrap();
    assert_eq!(cases.len(), 2);
    for case in cases {
        let expected: ExpectedEthDeposit =
            serde_json::from_value(case["expected"].clone()).unwrap();
        let receipt: CanonicalDepositReceipt =
            serde_json::from_value(case["receipt"].clone()).unwrap();
        assert_eq!(receipt.bridge_log.topics.len(), 3);
        let verified = verify_eth_deposit_source(&receipt, &expected).unwrap();
        assert_eq!(
            verified.destination_transaction_hash,
            case["expected_child_hash"].as_str().unwrap()
        );
        let child = CanonicalChildTransaction {
            hash: verified.destination_transaction_hash.clone(),
            chain_id: expected.destination_chain_id,
            transaction_type: 0x64,
            from: verified.aliased_sender.clone(),
            to: expected.recipient.clone(),
            value: expected.amount.clone(),
        };
        let receipt = CanonicalChildReceipt {
            transaction_hash: child.hash.clone(),
            success: true,
        };
        let credit = verify_eth_deposit_child(&child, &receipt, &verified).unwrap();
        assert_eq!(credit.amount, expected.amount);
        assert_eq!(credit.recipient, expected.recipient);
    }
}
